/* @lc app=leetcode id=3337 lang=kotlin */ class Solution { fun mul(a: Array<LongArray>, b: Array<LongArray>): Array<LongArray> = Array(26) { i -> LongArray(26) { j -> (0 until 26).fold(0L) { s, k -> (s + a[i][k] * b[k][j]) % 1_000_000_007L } } } fun lengthAfterTransformations(s: String, t: Int, nums: List<Int>): Int = Array(26) { i -> LongArray(26) { j -> if ((j - i + 26) % 26 in 1..nums[i]) 1L else 0L } }.let { base -> (30 downTo 0).fold(Array(26) { i -> LongArray(26) { j -> if (i == j) 1L else 0L } }) { r, b -> mul(r, r).let { sq -> if (t shr b and 1 == 1) mul(sq, base) else sq } }.let { p -> (s.sumOf { c -> p[c - 'a'].sum() } % 1_000_000_007L).toInt() } } }